import {
    naxDialog as showNaxDialog,
    naxDialogAlert,
    naxDialogConfirm
} from '@/uni_modules/nax-dialog/index.uts'

function onApiConfirm() {
    naxDialogConfirm({
        title: '确认',
        content: '使用命令式打开确认框'
    } as UTSJSONObject).then((res: UTSJSONObject) => {
        if (res.getBoolean('confirm') == true) {
            // 已确定
        }
    })
}

function onApiAlert() {
    naxDialogAlert({
        title: '提示',
        content: '这是一条告警信息'
    } as UTSJSONObject).then((res: UTSJSONObject) => {
        const action = res.getString('action')
        // action：'confirm' | 'cancel'
    })
}

function onApiDanger() {
    naxDialogConfirm({
        title: '删除',
        content: '删除后不可恢复',
        confirmText: '删除',
        confirmType: 'error'
    } as UTSJSONObject).then((res: UTSJSONObject) => {
        if (res.getBoolean('confirm') == true) {
            // 已删除
        }
    })
}

function onApiPromise() {
    showNaxDialog({
        title: 'Promise',
        content: '等待你的选择',
        showCancel: true
    } as UTSJSONObject).then((res: UTSJSONObject) => {
        const action = res.getString('action')
        // action：'confirm' | 'cancel'
    })
}
